public class RetryController {
    public void execute(RetryableOperation operation) {
        int attempt = 0;
        while (attempt < 3) {
            try {
                return operation.execute();
            } catch (Exception e) {
                attempt++;
                if (attempt == 3) {
                    throw new RuntimeException(e);
                }
                Thread.sleep(1000 + (int) Math.pow(2, attempt));
            }
        }
    }
}
```
