import org.springframework.data.redis.core.RedisTemplate;
import redis.clients.jedis.Jedis;

public class RateLimiter {
    private final RedisTemplate<String, String> redisTemplate;
    private final Jedis jedis;

    public RateLimiter(RedisTemplate<String, String> redisTemplate) {
        this.redisTemplate = redisTemplate;
        this.jedis = new Jedis("localhost");
    }

    public boolean isRateLimited(String requestKey) {
        String rateLimitInfo = redisTemplate.opsForValue().get(requestKey);
        if (rateLimitInfo != null) {
            // parse rate limit information from Redis
            int maxRequests = Integer.parseInt(rateLimitInfo.split(":")[1]);
            int currentRequests = jedis.incr(requestKey);
            return currentRequests >= maxRequests;
        }
        return false;
    }
}

